import streamlit as st
import json
import os
import sys

# Ensure src/ is in the python path
sys.path.append(os.path.dirname(os.path.abspath(__file__)))

from extractor import IntakeExtractorAgent, get_api_key, set_api_key
from orchestrator import TriageOrchestrator

def get_sample_note():
    # Look for the dataset generated by loader.py
    dataset_path = os.path.join(os.path.dirname(os.path.dirname(__file__)), "data", "dataset.jsonl")
    if not os.path.exists(dataset_path):
        return "No sample data found. Please run data/loader.py to generate sample notes."
    
    with open(dataset_path, "r") as f:
        line = f.readline()
        if not line:
            return ""
        record = json.loads(line)
        note = record.get("text", "") or record.get("note", "")
        if not note:
            note = list(record.values())[0] if record else ""
        return note

st.set_page_config(page_title="Patient Triage System", layout="wide")

st.title("🏥 Intelligent Patient Triage System")
st.markdown("This system uses **Gemini** to extract structured data from unstructured clinical notes, and a **Strands Decider** orchestrator to automatically assign the appropriate clinical triage level.")

# Sidebar Configuration
with st.sidebar:
    st.header("⚙️ Configuration")
    api_key_val = get_api_key() or ""
    
    if api_key_val:
        st.success("API Key detected ✓")
    else:
        st.warning("No API Key detected ⚠️")
        
    user_api_key = st.text_input(
        "Gemini API Key:",
        value=api_key_val,
        type="password",
        help="Enter your Google Gemini API key. This will be saved to config.json."
    )
    if st.button("Save API Key"):
        if user_api_key.strip():
            set_api_key(user_api_key.strip(), save_to_config=True)
            st.success("API Key saved to config.json!")
            st.rerun()
        else:
            st.error("Please enter a non-empty API key.")

# Initialize the agents
@st.cache_resource
def get_agents():
    return IntakeExtractorAgent(), TriageOrchestrator()

try:
    extractor, orchestrator = get_agents()
except Exception as e:
    st.error(f"Failed to initialize agents: {e}")
    st.stop()

if not get_api_key():
    st.warning("⚠️ **Gemini API Key is not set.** Please provide your Gemini API key in the sidebar to enable extraction.")

if "note_input" not in st.session_state:
    st.session_state.note_input = get_sample_note()

if "is_running" not in st.session_state:
    st.session_state.is_running = False

if "triage_data" not in st.session_state:
    st.session_state.triage_data = None

def start_triage():
    st.session_state.is_running = True
    st.session_state.triage_data = None

st.subheader("Patient Clinical Note Intake")

# Model selection
selected_model = st.selectbox(
    "Select Extraction Model:",
    [
        "models/gemini-3.5-flash", 
        "models/gemini-3.0-flash", 
        "models/gemini-2.5-flash", 
        "models/gemini-2.5-pro"
    ],
    index=0,
    disabled=st.session_state.is_running
)
# Update the extractor's model dynamically before running
extractor.model_name = selected_model

st.text_area(
    "Enter the unstructured clinical note below (or use the sample provided):",
    key="note_input",
    height=300,
    disabled=st.session_state.is_running
)

has_api_key = bool(get_api_key())

st.button(
    "Run Triage", 
    type="primary", 
    on_click=start_triage, 
    disabled=st.session_state.is_running or not has_api_key
)

if st.session_state.is_running:
    clinical_note = st.session_state.note_input
    if not clinical_note.strip():
        st.warning("Please enter a clinical note to triage.")
        st.session_state.is_running = False
        st.rerun()
    else:
        with st.spinner("Extracting patient data and deciding triage level..."):
            try:
                # 1. Extract unstructured note to structured Pydantic object
                patient = extractor.extract(clinical_note)
                # 2. Pass structured data to Orchestrator to make a decision
                triage_result = orchestrator.triage_patient(patient)
                st.session_state.triage_data = (patient, triage_result)
            except Exception as e:
                error_str = str(e).lower()
                if "429" in error_str or "quota" in error_str or "exhausted" in error_str:
                    st.error(f"⚠️ **Rate Limit Exceeded** for `{selected_model}`! Please swap to a different model in the dropdown above or wait a minute.")
                    st.toast("Model limit reached!", icon="🛑")
                else:
                    st.error(f"An error occurred during extraction. Please check your API key and try again.\n\nError: {e}")
        
        st.session_state.is_running = False
        st.rerun()

# Display results if available
if st.session_state.triage_data is not None:
    patient, triage_result = st.session_state.triage_data
    
    st.success("Extraction & Triage Complete!")
    col1, col2 = st.columns(2)
    
    with col1:
        st.subheader("📋 Structured Patient Data")
        st.json(patient.model_dump())
        
    with col2:
        st.subheader("⚖️ Final Decision")
        
        # Add visual indicators based on severity
        if "Level 1" in triage_result:
            st.error(f"🚨 **{triage_result}**")
        elif "Level 2" in triage_result:
            st.warning(f"⚠️ **{triage_result}**")
        elif "Level 3" in triage_result:
            st.info(f"⏱️ **{triage_result}**")
        else:
            st.success(f"✅ **{triage_result}**")
